begin;
do $test$
declare u uuid;c uuid;v uuid;w uuid;outside uuid;dep uuid:=gen_random_uuid();request uuid:=gen_random_uuid();source uuid:=gen_random_uuid();a uuid;b uuid;task uuid;x jsonb;
begin
 select id,company_id into u,c from public.profiles where active and role='employee' and (select count(*) from public.profiles q where q.company_id=profiles.company_id and q.active)>=3 order by created_at limit 1;
 if u is null then raise exception 'Fixture needs an active employee and two teammates';end if;
 select id into v from public.profiles where company_id=c and active and id<>u order by id limit 1;
 select id into w from public.profiles where company_id=c and active and id not in(u,v) order by id limit 1;
 select id into outside from public.profiles where company_id<>c and active order by id limit 1;
 if outside is null then raise exception 'Fixture needs another company for isolation test';end if;
 insert into public.departments(id,company_id,name) values(dep,c,'Rollback member assignment group');
 update public.profiles set department_id=dep where id in(v,w);
 perform set_config('request.jwt.claim.sub',u::text,true);
 x:=private.myday_suite('assign_people',null,'{}');
 if not exists(select 1 from jsonb_array_elements(x->'people') p where p->>'id'=v::text) then raise exception 'Teammate missing';end if;
 if exists(select 1 from jsonb_array_elements(x->'people') p where p->>'id'=outside::text) then raise exception 'Cross-company member listed';end if;
 perform private.myday_action(source,'create',jsonb_build_object('title','Rollback private task','details','Private original notes'));
 x:=private.myday_suite('assign_many',request,jsonb_build_object('source_task',source,'details','Explicit shared instructions','recipient_ids',jsonb_build_array(v),'department_ids',jsonb_build_array(dep)));
 if (x->>'sent')::int<>2 then raise exception 'Employee department deduplication failed';end if;
 perform private.myday_suite('assign_many',request,jsonb_build_object('source_task',source,'details','Explicit shared instructions','recipient_ids',jsonb_build_array(v),'department_ids',jsonb_build_array(dep)));
 if (select count(*) from private.myday_assignments where creator_id=u and source_task=source)<>2 then raise exception 'Retry duplicates';end if;
 select id into a from private.myday_assignments where creator_id=u and source_task=source and recipient_id=v;
 select id into b from private.myday_assignments where creator_id=u and source_task=source and recipient_id=w;
 if exists(select 1 from private.myday_assignments where id in(a,b) and (status<>'pending' or recipient_task is not null or details<>'Explicit shared instructions')) then raise exception 'Acceptance/privacy boundary failed';end if;
 begin perform private.myday_suite('accept',a,'{}');raise exception 'Sender accepted for recipient';exception when insufficient_privilege then null;end;
 begin perform private.myday_suite('assign_many',gen_random_uuid(),jsonb_build_object('title','Forbidden cross company','recipient_ids',jsonb_build_array(outside)));raise exception 'Cross-company assignment allowed';exception when insufficient_privilege then null;end;
 begin perform private.myday_suite('assign_many',gen_random_uuid(),jsonb_build_object('title','Forbidden department','department_ids',jsonb_build_array(gen_random_uuid())));raise exception 'Foreign department allowed';exception when insufficient_privilege then null;end;
 update public.profiles set active=false where id=w;
 begin perform private.myday_suite('assign_many',gen_random_uuid(),jsonb_build_object('title','Inactive target','recipient_ids',jsonb_build_array(w)));raise exception 'Inactive recipient allowed';exception when insufficient_privilege then null;end;
 update public.profiles set active=true where id=w;
 perform set_config('request.jwt.claim.sub',v::text,true);
 begin perform private.myday_suite('assign_many',gen_random_uuid(),jsonb_build_object('source_task',source,'recipient_ids',jsonb_build_array(u)));raise exception 'Another member source allowed';exception when insufficient_privilege then null;end;
 perform private.myday_suite('accept',a,'{}');
 select recipient_task into task from private.myday_assignments where id=a;
 if not exists(select 1 from public.actions where id=task and owner_id=v and company_id=c and details='Explicit shared instructions') then raise exception 'Accepted task content/owner incorrect';end if;
 if not exists(select 1 from public.actions where id=source and owner_id=u and details='Private original notes') then raise exception 'Original task modified';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);
 perform private.myday_suite('decline',b,'{}');
 if not exists(select 1 from private.myday_assignments where id=b and status='declined' and recipient_task is null) then raise exception 'Decline failed';end if;
 update public.profiles set active=false where id=u;
 perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform private.myday_suite('assign_many',gen_random_uuid(),jsonb_build_object('title','Inactive sender','recipient_ids',jsonb_build_array(v)));raise exception 'Inactive sender allowed';exception when insufficient_privilege then null;end;
end $test$;
rollback;
select 'Passed: employee multi-recipient/department assignment, deduplication/retry safety, acceptance/decline, private notes, source ownership, inactive membership and company isolation; all fixtures rolled back' as result;
